INSERT INTO still_zone_content (mood, context, support_type, time_key, action_type, message, display_time, is_active, sort_order) VALUES
('anxious', 'still', 'visual-breathing', '1min', 'BREATHE', 'Take a slow breath in. Pause at the top, two, three, four. Exhale gently for five. Feel yourself grounded. Feel yourself calm.', 60, true, 0),
('anxious', 'still', 'visual-breathing', '1min', 'BREATHE', 'Take two short breaths in through the nose. Then release it with a long, slow exhale. We''ll do five rounds. With each round let the exhale soften you.', 60, true, 1),
('anxious', 'still', 'visual-breathing', '1min', 'BREATHE', 'Try a soft box breath. Inhale for four, hold for two, exhale for four, pause here for two. We will repeat this six times.', 60, true, 2),
('anxious', 'still', 'visual-breathing', '1min', 'BREATHE', 'We''re going to try triangle breathing. Inhale for three, exhale for three, pause for three. Repeat this cycle ten times, gently.', 60, true, 3),
('anxious', 'still', 'visual-breathing', '1min', 'BREATHE', 'Inhale for five seconds, exhale for six seconds. Slowly complete eight cycles. Remember, do not strain, but breathe calmly with intention.', 60, true, 4),
('anxious', 'still', 'visual-breathing', '1min', 'BREATHE', 'Let your breath out be slightly longer than your breath in. Breathe in softly. And breathe out just a little slower. Continue like this for a couple of minutes, allowing the longer exhale to settle your body.', 60, true, 5),
('anxious', 'still', 'visual-breathing', '1min', 'BREATHE', 'Take a slow breath in. Now purse your lips gently, as if you''re cooling hot soup. Exhale slowly through the lips. Again. We will do ten slow, steady exhales, soft and controlled.', 60, true, 6),
('anxious', 'still', 'visual-breathing', '1min', 'BREATHE', 'Take a breath in. As you breathe out, begin counting down slowly from eight… seven… six… all the way down to one. If you lose your place, that''s okay. Simply begin again. Repeat the countdown once more, easy and unhurried.', 60, true, 7),
('anxious', 'still', 'visual-breathing', '1min', 'BREATHE', 'Bring your attention to the sensation of breath at your nostrils. Feel the coolness as you breathe in. The warmth as you breathe out. If your mind drifts, gently return to that feeling.', 60, true, 8),
('anxious', 'still', 'visual-breathing', '1min', 'BREATHE', 'Take a slow breath in. As you exhale, soften your jaw. Let your tongue rest. Let your teeth part slightly. Continue for twelve easy breaths, releasing tension each time you breathe out.', 60, true, 9);
INSERT INTO still_zone_content (mood, context, support_type, time_key, action_type, message, display_time, is_active, sort_order) VALUES
('anxious', 'still', 'visual-breathing', '2min', 'BREATHE', 'Breathe in and silently say, "Here." Breathe out and silently say, "Now." Again. "Here." "Now." Continue for twelve slow, steady cycles.', 120, true, 0),
('anxious', 'still', 'visual-breathing', '2min', 'BREATHE', 'Breathe in for four seconds and out for six seconds. No holding. Just gentle, steady breathing. Complete eight calm cycles.', 120, true, 1),
('anxious', 'still', 'visual-breathing', '2min', 'BREATHE', 'Take a big natural breath in. As you exhale, let it be thin and slow, like you''re breathing out through a straw. Inhale normally. Exhale long and narrow. Continue for ten breaths.', 120, true, 2),
('anxious', 'still', 'visual-breathing', '2min', 'BREATHE', 'Breathe in for five seconds and exhale over seven seconds. As you breathe out, let your shoulders drop. Repeat for six times.', 120, true, 3),
('anxious', 'still', 'visual-breathing', '2min', 'BREATHE', 'Take a breath in. As you exhale, make it slightly longer than the inhale and pause gently for three seconds at the end. Then allow the next inhale to arrive. Continue for eight calm cycles.', 120, true, 4),
('anxious', 'still', 'visual-breathing', '2min', 'BREATHE', 'Breathe in soft and deep. As you exhale slowly, imagine being in your favourite calming space. Repeat 10 times.', 120, true, 5),
('anxious', 'still', 'visual-breathing', '2min', 'BREATHE', 'Let the inhale come naturally, without effort. As you breathe out, let your belly soften. Continue for ten easy breaths.', 120, true, 6),
('anxious', 'still', 'visual-breathing', '2min', 'BREATHE', 'Take a normal breath in and out. In the next breath, increase the exhale time. Then return to one normal breath. Alternate like this ten times.', 120, true, 7),
('anxious', 'still', 'visual-breathing', '2min', 'BREATHE', 'Keep your eyes shut. Take a slow breath in. As you exhale through your mouth, imagine lightly fogging a mirror. Continue for ten calm breaths.', 120, true, 8),
('anxious', 'still', 'visual-breathing', '2min', 'BREATHE', 'Breathe in for three seconds and let the slower exhale for six seconds trigger relaxing your whole body. Complete ten rounds.', 120, true, 9);
INSERT INTO still_zone_content (mood, context, support_type, time_key, action_type, message, display_time, is_active, sort_order) VALUES
('anxious', 'still', 'visual-breathing', '3min', 'BREATHE', 'Take a breath in. As you exhale, relax your shoulders. Continue for three minutes allowing the shoulders to relax more and more.', 180, true, 0),
('anxious', 'still', 'visual-breathing', '3min', 'BREATHE', 'Breathe in. After each slow exhale, silently say, "I am Resetting". Continue for three minutes.', 180, true, 1),
('anxious', 'still', 'visual-breathing', '3min', 'BREATHE', 'Take a slow and deep inhale. As you exhale, silently say, "I''m at Peace, Steady and Calm." Let the words fill the exhale. Keep repeating for three minutes.', 180, true, 2),
('anxious', 'still', 'visual-breathing', '3min', 'BREATHE', 'Breathe in for four seconds, hold for four seconds, and exhale for seven seconds as you imagine your head and neck relaxing. Continue for three minutes.', 180, true, 3),
('anxious', 'still', 'visual-breathing', '3min', 'BREATHE', 'Take a deep inhale and a slow longer exhale. Focus on sensing the air entering and leaving your nostrils. Continue for three minutes.', 180, true, 4),
('anxious', 'still', 'visual-breathing', '3min', 'BREATHE', 'Take one normal breath in and out. Then repeat with a longer inhale and exhale. Alternate between the short and long breathing for three minutes.', 180, true, 5),
('anxious', 'still', 'visual-breathing', '3min', 'BREATHE', 'Breathe in slow and gentle. Let your exhale be longer as you picture your favourite flower. Continue for three minutes.', 180, true, 6),
('anxious', 'still', 'visual-breathing', '3min', 'BREATHE', 'Breathe in slowly and as you exhale, imagine dropping some weight from your chest. Let it fall away, releasing a little more burden each cycle. Keep repeating for three minutes.', 180, true, 7),
('anxious', 'still', 'visual-breathing', '3min', 'BREATHE', 'Breathe in for four seconds, hold for four seconds and exhale slowly over 6 seconds. At the end of the exhale repeat "I am in control, I''m OK" and continue for three minutes.', 180, true, 8),
('anxious', 'still', 'visual-breathing', '3min', 'BREATHE', 'Do ten rapid shallow breaths followed by two breaths with a slow long inhale and exhale. Repeat this cycle of ten rapid and two long breaths for 3 minutes. Feel the calm.', 180, true, 9);
INSERT INTO still_zone_content (mood, context, support_type, time_key, action_type, message, display_time, is_active, sort_order) VALUES
('anxious', 'still', 'audio-tool', '1min', 'LISTEN', 'In a moment, you''ll hear the sound of rain on glass. As you listen, notice the different layers of sound. See if you can find the farthest layer in the distance. Let your attention rest there as the sound continues.', 60, true, 0),
('anxious', 'still', 'audio-tool', '1min', 'LISTEN', 'You''re about to hear the sound of ocean waves. Allow your breath to follow the rhythm of the swell. Breathing in as the wave rises… And breathing out as it falls.', 60, true, 1),
('anxious', 'still', 'audio-tool', '1min', 'LISTEN', 'In a moment, you''ll hear a steady pink noise. Notice how constant and even the sound is. Let that steadiness guide your attention.', 60, true, 2),
('anxious', 'still', 'audio-tool', '1min', 'LISTEN', 'You''ll hear a single singing bowl. Listen closely as the tone rings out. Follow the sound all the way until it fades into silence.', 60, true, 3),
('anxious', 'still', 'audio-tool', '1min', 'LISTEN', 'You''re about to hear the sounds of a forest. As the audio begins, choose one layer to focus on. Perhaps the wind… the leaves… or the birds. Let that single sound hold your attention.', 60, true, 4),
('anxious', 'still', 'audio-tool', '1min', 'LISTEN', 'You''ll hear a low, steady brown noise. Imagine the sound as a soft blanket surrounding you. Let it settle gently around your awareness.', 60, true, 5),
('anxious', 'still', 'audio-tool', '1min', 'LISTEN', 'You''re about to hear a soft metronome. Allow the rhythm to guide you. Breathe naturally, and let every second beat cue a slow exhale.', 60, true, 6),
('anxious', 'still', 'audio-tool', '1min', 'LISTEN', 'You''ll hear gentle chimes. Each time a chime sounds, allow your exhale to lengthen slightly. Let the sound guide the rhythm of your breath.', 60, true, 7),
('anxious', 'still', 'audio-tool', '1min', 'LISTEN', 'In a moment, you''ll hear the sound of a quiet stream. Let your attention settle on the middle layer of the sound. Rest there, simply listening.', 60, true, 8),
('anxious', 'still', 'audio-tool', '1min', 'LISTEN', 'You''re about to hear a gentle breathing rhythm. Let the sound guide your breath in… and out. There''s no need to hold the breath. Just follow the pace comfortably.', 60, true, 9);
INSERT INTO still_zone_content (mood, context, support_type, time_key, action_type, message, display_time, is_active, sort_order) VALUES
('anxious', 'still', 'audio-tool', '2min', 'LISTEN', 'As the audio begins, you''ll hear a soft white noise. Let your jaw soften and allow your breathing to settle naturally as you listen.', 120, true, 0),
('anxious', 'still', 'audio-tool', '2min', 'LISTEN', 'You''re about to hear a simple piano loop. For the next moment, there''s nothing to do. Just listen.', 120, true, 1),
('anxious', 'still', 'audio-tool', '2min', 'LISTEN', 'You''ll soon hear a bell every few seconds. Each time the bell sounds, quietly remind yourself: "This passes."', 120, true, 2),
('anxious', 'still', 'audio-tool', '2min', 'LISTEN', 'You''re about to hear a soft humming sound. Let your exhale grow slightly longer than your inhale. Allow the sound to carry you into a steady rhythm.', 120, true, 3),
('anxious', 'still', 'audio-tool', '2min', 'LISTEN', 'You''ll hear two short prompts. "Feet" and later, "Hands". Just breathe normally, but at each prompt focus and feel that body part relax.', 120, true, 4),
('anxious', 'still', 'audio-tool', '2min', 'LISTEN', 'As the audio begins, you''ll hear the sound of quiet paper turning. Let your attention settle into the small details of the sound.', 120, true, 5),
('anxious', 'still', 'audio-tool', '2min', 'LISTEN', 'You''re about to hear wind moving through trees. Allow your attention to stay wide and open. Simply receiving the sound.', 120, true, 6),
('anxious', 'still', 'audio-tool', '2min', 'LISTEN', 'You''ll hear a slow, heartbeat-like drum. Let your breath move naturally to the rhythm.', 120, true, 7),
('anxious', 'still', 'audio-tool', '2min', 'LISTEN', 'You''re about to hear a short, simple story. As you listen, allow your body to soften and settle. Try imaging the scene as it plays out.', 120, true, 8),
('anxious', 'still', 'audio-tool', '2min', 'LISTEN', 'You''ll hear the quiet murmur of a café in the background. Imagine sitting there comfortably, unnoticed.', 120, true, 9);
INSERT INTO still_zone_content (mood, context, support_type, time_key, action_type, message, display_time, is_active, sort_order) VALUES
('anxious', 'still', 'audio-tool', '3min', 'LISTEN', 'You will soon hear a prompt. Let the words land softly and imagine how it could shape your thoughts. "You can slow down. You deserve this brief moment of reflection."', 180, true, 0),
('anxious', 'still', 'audio-tool', '3min', 'LISTEN', 'You''ll hear a gentle tone to focus on. If your mind wanders, come back to the tone and let it envelope you.', 180, true, 1),
('anxious', 'still', 'audio-tool', '3min', 'LISTEN', 'You''re about to hear distant thunder. Each time you hear a rumble, allow yourself a long, slow exhale and find calmness in this storm.', 180, true, 2),
('anxious', 'still', 'audio-tool', '3min', 'LISTEN', 'You will hear the sounds of insects moving gently through a warm summer evening. Concentrate on the steady rhythm and repetition in the sound.', 180, true, 3),
('anxious', 'still', 'audio-tool', '3min', 'LISTEN', 'You''re about to hear soft flute and strings. Each time you exhale, focus on relaxing a body part starting from your feet and working up to the top of your head.', 180, true, 4),
('anxious', 'still', 'audio-tool', '3min', 'LISTEN', 'You''ll hear light rainfall and birds. Try to picture the scene and see if you can notice three different layers in the soundscape. Can you hear wind, rain, birds? Or all three?', 180, true, 5),
('anxious', 'still', 'audio-tool', '3min', 'LISTEN', 'Breathe normally and reflect internally and externally on the grounding prompt you are about to hear. "You have arrived to be aware".', 180, true, 6),
('anxious', 'still', 'audio-tool', '3min', 'LISTEN', 'You''ll hear a short sequence of words. Simply let yourself melt into those feelings. "Thinking… feeling… letting-go."', 180, true, 7),
('anxious', 'still', 'audio-tool', '3min', 'LISTEN', 'You may hear a gentle breath-counting rhythm. Just follow along and let calm and relaxation seep in.', 180, true, 8),
('anxious', 'still', 'audio-tool', '3min', 'LISTEN', 'When the audio finishes, reflect on how your body feels. Take slow breaths and sense the calm that remains.', 180, true, 9);
INSERT INTO still_zone_content (mood, context, support_type, time_key, action_type, message, display_time, is_active, sort_order) VALUES
('anxious', 'still', 'immediate-advice', '1min', 'ACTION', 'Pause for a moment. Remind yourself: This is anxiety, not danger. You''re doing okay. You don''t have to solve everything right now. Simply focus on the next single task in front of you.', 60, true, 0),
('anxious', 'still', 'immediate-advice', '1min', 'ACTION', 'Breathe normally. Cut out the multiple thoughts and ask yourself: What needs my attention most? Just that. Think of nothing more.', 60, true, 1),
('anxious', 'still', 'immediate-advice', '1min', 'ACTION', 'Breathe slowly and turn your mind to what is happening right now, and how you feel.', 60, true, 2),
('anxious', 'still', 'immediate-advice', '1min', 'ACTION', 'You don''t have to feel perfectly calm. Right now, aim for steady. Steady is enough.', 60, true, 3),
('anxious', 'still', 'immediate-advice', '1min', 'ACTION', 'If you find yourself checking to see if things are improving, pause. Let the process work without measuring it. You''re allowed to simply continue.', 60, true, 4),
('anxious', 'still', 'immediate-advice', '1min', 'ACTION', 'So much effort to deal with how you feel. Just dial down that effort with each slow breath, and notice how your body settles easily when it''s not pushed so hard.', 60, true, 5),
('anxious', 'still', 'immediate-advice', '1min', 'ACTION', 'If something important needs deciding, give it time. Remember that big decisions can wait until your body feels steadier.', 60, true, 6),
('anxious', 'still', 'immediate-advice', '1min', 'ACTION', 'Instead of asking "why can''t I settle anything," try asking: "How can I settle just ten percent?" Focus on that one small task for a minute.', 60, true, 7),
('anxious', 'still', 'immediate-advice', '1min', 'ACTION', 'Let anxious thoughts be like background radio noise. You don''t need to acknowledge them. Let them play quietly while you continue with your moment.', 60, true, 8),
('anxious', 'still', 'immediate-advice', '1min', 'ACTION', 'Remind yourself: You only have to manage this moment. Not the whole day. Just here and now.', 60, true, 9);
INSERT INTO still_zone_content (mood, context, support_type, time_key, action_type, message, display_time, is_active, sort_order) VALUES
('anxious', 'still', 'immediate-advice', '2min', 'ACTION', 'If the problems you''re facing feel too big, you''re allowed to shrink them down. What is one small thing you can focus on today?', 120, true, 0),
('anxious', 'still', 'immediate-advice', '2min', 'ACTION', 'Speak to yourself with neutral or positive language. If you have negative thoughts, they remain agitated in the body. Let them dissipate and rise above. This is activation.', 120, true, 1),
('anxious', 'still', 'immediate-advice', '2min', 'ACTION', 'Try to imagine your body relaxing. Unclench your jaw for a moment. Let your shoulders soften. Feel this release throughout your body. Then return to what you were doing, without analysing it.', 120, true, 2),
('anxious', 'still', 'immediate-advice', '2min', 'ACTION', 'For the next two minutes, release yourself from the feeling of needing to fix everything. Simply sit, and rest and allow yourself this moment.', 120, true, 3),
('anxious', 'still', 'immediate-advice', '2min', 'ACTION', 'If the outcome seems too large, change the goal slightly. Your job right now is simply to practise the skill. Not to perfect the outcome. Practising is enough.', 120, true, 4),
('anxious', 'still', 'immediate-advice', '2min', 'ACTION', 'If the feeling of restlessness rises like a wave, let it form at its peak, and break. Imagine your anxiety breaking with the wave, and flowing out to sea. For the next couple of minutes, your only job is to imagine this wave breaking and to remember that the peak of restlessness cannot last forever.', 120, true, 5),
('anxious', 'still', 'immediate-advice', '2min', 'ACTION', 'Think of one kind sentence you might say to a friend in this moment. Now offer those same words to yourself and reflect on how that makes you feel.', 120, true, 6),
('anxious', 'still', 'immediate-advice', '2min', 'ACTION', 'Close your eyes, breathe normally and find one simple detail around you to reflect upon. Just let your attention rest there.', 120, true, 7),
('anxious', 'still', 'immediate-advice', '2min', 'ACTION', 'Remember that you are allowed to be imperfect, to be normal, to re-do. There is no one path to your success, you can take the next step imperfectly. The goal should always be simply taking the step.', 120, true, 8),
('anxious', 'still', 'immediate-advice', '2min', 'ACTION', 'If things feel urgent, slow them into sequence. First one step. Then the next. There is nothing else to focus on right now.', 120, true, 9);
INSERT INTO still_zone_content (mood, context, support_type, time_key, action_type, message, display_time, is_active, sort_order) VALUES
('anxious', 'still', 'immediate-advice', '3min', 'ACTION', 'Take a minute to remind yourself: You can carry some discomfort and still function. You''re doing okay. And you will be okay.', 180, true, 0),
('anxious', 'still', 'immediate-advice', '3min', 'ACTION', 'If your mind is telling a dramatic and disturbing story, gently label it as: the catastrophe story. Then return to the present moment with slow breaths to find peace.', 180, true, 1),
('anxious', 'still', 'immediate-advice', '3min', 'ACTION', 'Remind yourself that you don''t need perfection and certainty right now. You only need the next small step.', 180, true, 2),
('anxious', 'still', 'immediate-advice', '3min', 'ACTION', 'If you feel the urge to escape or fix everything quickly, remember that these feelings are not permanent, they are like the weather, they come and go. You don''t have to act on them immediately.', 180, true, 3),
('anxious', 'still', 'immediate-advice', '3min', 'ACTION', 'Choose one simple anchor. The feeling of air in your breath… The chair beneath you… Your feet on the floor. Return to your favourite anchor whenever you need.', 180, true, 4),
('anxious', 'still', 'immediate-advice', '3min', 'ACTION', 'If you notice using words like ''must'' or ''should'' in your thoughts, soften them. Try replacing them with ''I choose'' or ''I prefer''. Let the pressure ease a little.', 180, true, 5),
('anxious', 'still', 'immediate-advice', '3min', 'ACTION', 'For the next three minutes, allow "good enough" to be the standard. You don''t have to push beyond that.', 180, true, 6),
('anxious', 'still', 'immediate-advice', '3min', 'ACTION', 'If you find yourself monitoring every symptom, take a moment to pause. Constantly checking just worsens the disturbance. Instead, allow your attention to rest elsewhere, on something pleasant and calm.', 180, true, 7),
('anxious', 'still', 'immediate-advice', '3min', 'ACTION', 'Remember to give yourself some credit. Practising this moment counts. When you still feel unsettled, your self reward will protect you.', 180, true, 8),
('anxious', 'still', 'immediate-advice', '3min', 'ACTION', 'Take three slow breaths, with long exhales. Let your jaw soften and your shoulders drop. Keep repeating.', 180, true, 9);
INSERT INTO still_zone_content (mood, context, support_type, time_key, action_type, message, display_time, is_active, sort_order) VALUES
('anxious', 'still', 'havening', '1min', 'ACTION', 'Place your hands on the opposite shoulder. Slowly stroke your arms down toward your elbows. Then back up again. Move gently and slowly, breathing out a little longer each time.', 60, true, 0),
('anxious', 'still', 'havening', '1min', 'ACTION', 'Rub your palms together for a few seconds, creating a little warmth. Now rest your palms lightly together. Feel the warmth between them as you breathe slowly.', 60, true, 1),
('anxious', 'still', 'havening', '1min', 'ACTION', 'Cross your arms and place your hands on your upper arms. Gently squeeze one side… then the other. Continue for a full minute.', 60, true, 2),
('anxious', 'still', 'havening', '1min', 'ACTION', 'Place your hands on your thighs and slowly slide them down to cup your knees. Then slowly but firmly slide them up the thighs again. Keep repeating.', 60, true, 3),
('anxious', 'still', 'havening', '1min', 'ACTION', 'Place your palms on your thighs. Press gently down for a few seconds. Then release. As you press down, breathe in, then slowly exhale and you stop pressing. Continue to repeat this.', 60, true, 4),
('anxious', 'still', 'havening', '1min', 'ACTION', 'Place one hand over your heart. Feel the warmth beneath your palm. Let your exhale grow slightly longer as you rest there.', 60, true, 5),
('anxious', 'still', 'havening', '1min', 'ACTION', 'Bring your thumb and forefinger together. Slowly stroke your thumb with your finger. With each exhale, remind yourself that you are in a safe space.', 60, true, 6),
('anxious', 'still', 'havening', '1min', 'ACTION', 'Hold something cool in your hands, like a bottle or a cup. Notice the coolness in your palms. Focus on that sensation as you breathe normally.', 60, true, 7),
('anxious', 'still', 'havening', '1min', 'ACTION', 'Bring your forearms together. Gently roll them against each other. Slow, soothing movement. Let your breath lengthen as you move.', 60, true, 8),
('anxious', 'still', 'havening', '1min', 'ACTION', 'Cup your ears with your palms. Gently press for five seconds and partially release for five seconds. Immerse yourself in the changing sound.', 60, true, 9);
